mapper.select:
select * from t_operate_log
AND operate_user_id = #{query.operateUserId}
AND operate_user_type = #{query.operateUserType}
AND create_time >= CAST(#{query.startDate} AS date)
AND create_time < CAST(#{query.endDate} AS date) + INTERVAL '1 day'
AND operate_user_name LIKE '%' || replace(replace(replace(#{query.userName}, '\', '\\'), '%', '\%'), '_', '\_') || '%'
AND (module LIKE '%' || replace(replace(replace(#{query.keywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%' OR content LIKE '%' || replace(replace(replace(#{query.keywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%')
AND (url LIKE '%' || replace(replace(replace(#{query.requestKeywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%' OR method LIKE '%' || replace(replace(replace(#{query.requestKeywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%' OR param LIKE '%' || replace(replace(replace(#{query.requestKeywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%' OR response LIKE '%' || replace(replace(replace(#{query.requestKeywords}, '\', '\\'), '%', '\%'), '_', '\_') || '%')
AND success_flag = #{query.successFlag}
order by create_time desc
